entries.definitions/workflows/reaction-productio:
{
  "schema_version": 1,
  "id": "reaction-production",
  "version": "0.2.0",
  "status": "design-only",
  "stages": [
    {
      "id": "clarify",
      "operation": "resolve format-specific inputs",
      "output": "brief",
      "instructions": "Ask one unresolved question at a time about the hook, values, reaction motion/source and presentation. The roughly 0.5-second repeated reaction is established; do not ask again what shaking means. Idk delegates creative choices, not missing footage."
    },
    {
      "id": "sequence",
      "operation": "plan context and reaction beats",
      "output": "plan",
      "instructions": "Pair each text or number state with its meaning against the same reaction loop. Plan readable text holds independently of loop duration; do not require a new facial expression or movement for each state."
    },
    {
      "id": "record",
      "operation": "obtain on-camera footage",
      "output": "video input",
      "instructions": "Use supplied footage or provide a performance plan for a short repeatable reaction, approximately 0.5 seconds. Yes/no head movement is optional. Do not invent footage or exact source timestamps."
    },
    {
      "id": "edit",
      "operation": "align text states and performance",
      "output": "video or edit plan",
      "instructions": "Select and repeat a clean reaction segment while overlaying the changing context states. Inspect loop boundaries; do not force text changes every 0.5 seconds. Resolve whether source audio is muted, retained or replaced so looped audio does not accidentally stutter. Resolve music and effects before adding them. Save a plan if rendering is unavailable."
    },
    {
      "id": "review",
      "operation": "inspect sequence",
      "output": "review notes",
      "instructions": "Check seamless repetition, text readability, intended context shifts, audio continuity and overall ending. Distinguish the reaction loop from whole-video looping. Report checks that were not performed."
    }
  ],
  "note": "Workflow operations are design descriptions, not installed commands or an implemented renderer."
}

entries.definitions/workflows/reduction-producti:
{
  "schema_version": 1,
  "id": "reduction-production",
  "version": "0.1.0",
  "status": "design-only",
  "stages": [
    {
      "id": "concept",
      "operation": "brainstorm concepts",
      "output": "concept",
      "instructions": "Identify a complex topic, the useful simplified takeaway, and why a broad audience should care."
    },
    {
      "id": "claim-check",
      "operation": "review supporting material",
      "output": "claim notes",
      "instructions": "Establish why the surprising claim is defensible and where simplification stops being accurate. Verify uncertain claims before presenting them as facts."
    },
    {
      "id": "hook",
      "operation": "brainstorm hooks",
      "output": "hook",
      "instructions": "Generate spoken openings plus hook-text options grounded in the same claim."
    },
    {
      "id": "script",
      "operation": "generate script",
      "output": "script",
      "instructions": "Follow the reductions structure; keep qualification near the end and finish with a follow CTA."
    },
    {
      "id": "record",
      "operation": "obtain narrator footage",
      "output": "video input",
      "instructions": "Request or use supplied recording; do not imply footage exists before it is provided."
    },
    {
      "id": "edit-plan",
      "operation": "plan cuts and treatments",
      "output": "plan",
      "instructions": "Resolve caption, SFX and optional animation decisions. Unselected media assets remain explicit gaps."
    },
    {
      "id": "edit",
      "operation": "execute with available editor",
      "output": "video",
      "instructions": "Remove dead air, add hook text and manual speech captions, and apply selected restrained effects. Return an edit plan if execution tools or media are unavailable."
    },
    {
      "id": "review",
      "operation": "inspect final export",
      "output": "review notes",
      "instructions": "Check accuracy, hook payoff, caption timing and legibility, dialogue clarity, natural pacing and CTA. Report unperformed checks."
    }
  ],
  "note": "Operations are workflow descriptions, not implemented commands or registered skill IDs."
}

entries.definitions/workflows/troll-production.j:
{
  "schema_version": 1,
  "id": "troll-production",
  "version": "0.1.0",
  "status": "design-only",
  "stages": [
    {
      "id": "intake",
      "instruction": "Resolve topic or seed, audience/in-group, shared knowledge, and count or length. Ask about engagement tactics if unresolved; none or delegation is valid."
    },
    {
      "id": "concept",
      "instruction": "Define the premise and desired audience reaction. Separate the actual shared knowledge from the narrator\u2019s deliberately wrong statement."
    },
    {
      "id": "hook",
      "instruction": "Find a natural opening that establishes the bit without announcing that it is a joke."
    },
    {
      "id": "script",
      "instruction": "Develop the intentional straight-faced bit. When comment bait is selected, connect the audience question to the absurd premise. Keep explanatory truth/bit notes in metadata rather than forcing a reveal."
    },
    {
      "id": "performance-plan",
      "instruction": "Specify straight-faced delivery and timing; resolve presentation choices before executing an edit."
    },
    {
      "id": "review",
      "instruction": "Check insider recognition, intentionality, delivery and relevance of the audience question. Do not evaluate the bit as if it were a reductions explainer."
    }
  ],
  "note": "Stage descriptions are design contracts, not implemented generation tools."
}

